-- Explicit live voice purpose, independent from text, source audio and production grants.
ALTER TABLE policy_versions DROP CONSTRAINT policy_versions_kind_check;
ALTER TABLE policy_versions ADD CONSTRAINT policy_versions_kind_check CHECK(kind IN ('privacy_notice','private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies','private_chat_photo_storage','person_chat_image_replies','person_world_actions','person_story_branches','person_offline_life','production_model_execution','person_voice_calls'));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_purpose_check;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_purpose_check CHECK(purpose IN ('privacy_notice','private_story_storage','ai_text_processing','private_photo_storage','private_person_photo_storage','virtual_gift_storage','person_gift_returns','gift_delivery_photo_storage','private_letter_storage','person_letter_replies','person_gather_replies','private_chat_photo_storage','person_chat_image_replies','person_world_actions','person_story_branches','person_offline_life','production_model_execution','person_voice_calls'));
ALTER TABLE consent_events DROP CONSTRAINT consent_events_check;
ALTER TABLE consent_events ADD CONSTRAINT consent_events_check CHECK((purpose='privacy_notice' AND decision='acknowledge') OR (purpose<>'privacy_notice' AND decision IN ('grant','revoke')));

INSERT INTO policy_versions(id,kind,version,document_zh_cn,document_en) VALUES
('5b5b3cc7-afca-4206-82db-a3eab1c46827','person_voice_calls',1,
'西界实时 AI 语音通话授权（OpenAI Realtime）
本用途独立于文字聊天、声音样本保存和正式运行授权。只有你主动开始、同时允许文字资料保存，并允许本授权，才把当前麦克风实时音频及当前人物必要且已确认的称呼、关系、故事、人格、生平、口头禅和明确未知事项，送至 OpenAI Realtime 生成即时合成语音。服务端代理官方加密连接，默认标准合成声音 marin，可按你明确的明亮／低沉偏好选择官方 coral／cedar 标准声，不使用、克隆或模仿人物原声音样本，不声称本人意识或真实本人通话。
本片不读取旧聊天、照片、珍藏、自动长期记忆或其他人物资料；实时音频及模型可能生成的临时文字只在通道内处理，西界默认不录音、不持久保存逐字稿、不创建自动记忆或后续文字 AI 上下文。只保存可信通道建立、终止、模型/声音配置、来源版本和必要授权记录。实时通话协议不支持文字请求的 store:false 参数，不以此参数作语音留存承诺；提供方处理按其当前数据控制与运营配置执行。
每账号最多一个活跃通话，默认至多60秒，可由明确部署配置缩短或设置至多120秒；未建成真实双向通道不计作接通。时长由服务器可信连接和终止记录计算，失败、网络未知及未确认终止不得伪造接通或时长。实时通话另计模型每日尝试额度及并发，失败仍可能计次数，不消费你的虚拟资产。静音停止上传麦克风，挂断、退出账号、撤回、来源变化或超时停止通道；重授不恢复旧通话。正式环境还需另行当前正式 AI 运行授权和运营明确启用。
你可以在隐私设置撤回，不能收回已传给提供方的音频；已保存最小通话记录仍可按文字保存授权查看，导出和删除不要求重新授予本用途。影像入口仅为另行明确标识的动态照片预览，本授权不传输摄像头视频。',
'Xijie live AI voice call permission (OpenAI Realtime)
This purpose is separate from text chat, source audio storage and production permission. Only an explicit call with current private text storage and this grant sends live microphone audio and minimal authorized current-character profile to OpenAI Realtime. The server proxies the official encrypted connection. Standard synthetic voice marin is used by default; explicit bright or deep preferences select official coral or cedar; character audio is never cloned or imitated and no real consciousness is claimed.
Old chats, photos, treasures, automatic memory and other characters are excluded. Audio and any transient model text exist only inside the channel: Xijie records no audio or persistent transcript and creates no automatic memory or future text context. Only trusted connection/termination, model/voice, source version and necessary grants are retained. Realtime does not support the text request store:false field; provider processing follows its data controls and operator configuration.
One active call per account, default maximum60seconds and configurable up to120. A real bidirectional channel is required before connected status. Server timestamps alone determine confirmed duration; failures and unknown termination never fabricate connections or duration. Model daily attempt and concurrency limits apply even to failed attempts without spending virtual assets. Mute stops microphone transmission. Hangup, sign-out, withdrawal, changed sources or timeout stop the channel. Regrant never revives a call. Production additionally needs separate current production AI permission and explicit release approval.
Withdrawal cannot recall audio already sent to the provider. Minimal saved call records follow private text storage; export and erasure need no renewed voice grant. The separate image entry is only a clearly labeled animated photo preview, not live camera video.');

INSERT INTO policy_versions(id,kind,version,document_zh_cn,document_en)
SELECT id,kind,version+1,
 document_zh_cn || E'\n\n实时语音补充：正式运行可另行支持独立 person_voice_calls 用途，必须明确阅读并允许该用途。本片仅实时麦克风与当前人物最小画像，经官方 OpenAI Realtime 加密代理生成标准合成声音；无声线克隆，无旧私聊或记忆，不录音、不留逐字稿。Realtime 不接收文字请求的 store:false 字段，前文该字段仅指支持它的文字接口。其余数据隔离、明确范围、额度及撤回规则继续生效。',
 document_en || E'\n\nRealtime voice revision: production may additionally support the independent person_voice_calls purpose only with its separate current grant. Live microphone and minimal current character profile are proxied to official OpenAI Realtime for a standard synthetic voice, excluding cloning, prior chats and memory, recording and persistent transcripts. Realtime does not accept the text request store:false field; that earlier field applies only to text endpoints supporting it. All other isolation, scope, budget and withdrawal rules continue.'
FROM (SELECT * FROM policy_versions WHERE kind='production_model_execution' ORDER BY version DESC LIMIT 1)p;
